133→// ─── Loader / Action ─────────────────────────────────────────────────────────
134→
135→export const loader = async ({ request }: LoaderFunctionArgs) => {
136→  const { session } = await authenticate.admin(request);
137→  try {
138→    const dashboardData = await getDashboardStats(session.shop);
139→    return { data: dashboardData };
140→  } catch {
141→    return { data: EMPTY_STATS };
142→  }
