331→  quizzes,
332→  onEdit,
333→  onPreview,
334→  onCreate,
335→}: {
336→  quizzes: QuizRow[];
337→  onEdit: (id: string) => void;
338→  onPreview: (id: string) => void;
339→  onCreate: () => void;
340→}) {
341→  const { selectedResources, allResourcesSelected, handleSelectionChange } =
342→    useIndexResourceState(quizzes);
343→
344→  if (quizzes.length === 0) {
345→    return (
346→      <Card>
347→        <EmptyState
348→          heading="Build your first product quiz"
349→          action={{ content: "Create quiz", onAction: onCreate }}
350→          image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
351→        >
352→          <p>
