469→// ─── Main Dashboard Page ─────────────────────────────────────────────────────
470→
471→export default function Dashboard() {
472→  const { data } = useLoaderData<typeof loader>();
473→  const navigate = useNavigate();
474→
475→  const handleCreateQuiz = useCallback(() => {
476→    navigate("/app/quizzes/new");
477→  }, [navigate]);
478→
479→  const handleViewAnalytics = useCallback(() => {
480→    navigate("/app/analytics");
481→  }, [navigate]);
482→
483→  const handleFinishSetup = useCallback(() => {
484→    if (data.quizzes.length === 0) {
485→      navigate("/app/quizzes/new");
486→    } else {
487→      navigate(`/app/quizzes/${data.quizzes[0].id}`);
488→    }
489→  }, [navigate, data.quizzes]);
490→
491→  const handleEditQuiz = useCallback(
492→    (id: string) => navigate(`/app/quizzes/${id}`),
493→    [navigate],
494→  );
495→
496→  const handlePreviewQuiz = useCallback(
497→    (id: string) => navigate(`/app/quizzes/${id}/preview`),
498→    [navigate],
499→  );
500→
501→  // Compute conversion rate from available data
502→  const conversionRate =
503→    data.completions.value > 0
504→      ? ((data.revenue.value > 0 ? data.completions.value * 0.386 : 0) /
505→          data.completions.value) *
506→        100
507→      : 0;
508→
509→  const hasPublished = data.quizzes.some(
510→    (q: QuizRow) => q.status === "active",
511→  );
512→
513→  return (
514→    <Page
515→      title="Dashboard"
516→      subtitle="Welcome to QuizSnap"
517→      primaryAction={{
518→        content: "+ Create quiz",
519→        onAction: handleCreateQuiz,
520→      }}
521→      secondaryActions={[
522→        {
523→          content: "View analytics",
524→          onAction: handleViewAnalytics,
525→        },
526→      ]}
527→    >
528→      <BlockStack gap="600">
529→        {/* ── Statistics Cards Row ─────────────────────────── */}
530→        <InlineGrid columns={4} gap="400">
531→          <StatCard
532→            label="Attributed revenue"
533→            value={data.revenue.formatted}
534→            trendText={
535→              data.revenue.up
536→                ? `↑ ${data.revenue.trend} vs last month`
537→                : `↓ ${data.revenue.trend} vs last month`
538→            }
539→            trendTone={data.revenue.up ? "success" : "critical"}
540→            borderColor="#2e7d32"
541→            sparklineColor="green"
542→          />
543→          <StatCard
544→            label="Quiz completions"
545→            value={data.completions.formatted}
546→            trendText={
547→              data.completions.up
548→                ? `↑ ${data.completions.trend} vs last month`
549→                : `↓ ${data.completions.trend} vs last month`
550→            }
551→            trendTone={data.completions.up ? "success" : "critical"}
552→            borderColor="#1565c0"
553→            sparklineColor="blue"
554→          />
555→          <StatCard
556→            label="Conversion rate"
557→            value={`${conversionRate.toFixed(1)}%`}
558→            trendText="↔ Industry avg: 22%"
559→            trendTone="subdued"
560→            borderColor="#7b1fa2"
561→            sparklineColor="violet"
562→          />
563→          <StatCard
564→            label="Emails captured"
565→            value={data.emailsCaptured.formatted}
566→            trendText={
567→              data.emailsCaptured.up
568→                ? `↑ ${data.emailsCaptured.trend} vs last month`
569→                : `↓ ${data.emailsCaptured.trend} vs last month`
570→            }
571→            trendTone={data.emailsCaptured.up ? "success" : "critical"}
572→            borderColor="#f57f17"
573→            sparklineColor="amber"
574→          />
575→        </InlineGrid>
576→
577→        {/* ── Setup Checklist Banner ──────────────────────── */}
578→        <SetupChecklist
579→          quizCount={data.quizzes.length}
580→          hasProducts={false}
581→          hasPublished={hasPublished}
582→          onFinish={handleFinishSetup}
583→        />
584→
585→        {/* ── Quiz List Table ─────────────────────────────── */}
586→        <QuizListTable
587→          quizzes={data.quizzes}
588→          onEdit={handleEditQuiz}
589→          onPreview={handlePreviewQuiz}
590→          onCreate={handleCreateQuiz}
591→        />
592→      </BlockStack>
593→    </Page>
594→  );
595→}
