    { label: SETUP_STEPS[2].label, complete: hasPublished },
  ];

  const completedCount = steps.filter((s) => s.complete).length;
  const totalCount = steps.length;
  const progressPercent = Math.round((completedCount / totalCount) * 100);

  // Do not render if no quizzes exist yet, or all steps are done
  if (quizCount === 0 || completedCount === totalCount) return null;

  // Build the inline step list — completed steps run together with dot separators,
  // pending steps appear after as subdued text.
  const completedSteps = steps.filter((s) => s.complete);
  const pendingSteps = steps.filter((s) => !s.complete);

  return (
    <Card>
      <InlineStack align="space-between" blockAlign="start" gap="400" wrap={false}>
        {/* Left: gear icon circle */}
        <div
          style={{
            width: 36,
            height: 36,
            borderRadius: "50%",
            background: "var(--p-color-bg-fill-info-secondary)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            flexShrink: 0,
          }}
        >
          <div style={{ width: 20, height: 20, color: "var(--p-color-icon-info)" }}>
            <SettingsIcon />
          </div>
        </div>

        {/* Centre: title + progress bar + inline steps */}
        <Box width="100%">
          <BlockStack gap="200">
            <Text as="h2" variant="headingMd" fontWeight="bold">
              Setup checklist — {completedCount} of {totalCount} steps done
            </Text>

            <ProgressBar progress={progressPercent} size="small" tone="primary" />

            {/* Inline step labels */}
            <InlineStack gap="200" blockAlign="center" wrap>
              {completedSteps.map((step, i) => (
                <InlineStack key={step.label} gap="100" blockAlign="center">
                  {i > 0 && (
                    <Text as="span" variant="bodySm" tone="subdued">
                      ·
                    </Text>
                  )}
                  <Text as="span" variant="bodySm" tone="success">
                    ✓ {step.label}
                  </Text>
                </InlineStack>
              ))}

              {completedSteps.length > 0 && pendingSteps.length > 0 && (
                <Text as="span" variant="bodySm" tone="subdued">
                  ·
                </Text>
              )}

              {pendingSteps.map((step, i) => (
                <InlineStack key={step.label} gap="100" blockAlign="center">
                  {i > 0 && (
                    <Text as="span" variant="bodySm" tone="subdued">
                      ·
                    </Text>
                  )}
                  <Text as="span" variant="bodySm" tone="subdued">
                    ○ {step.label}
                  </Text>
                </InlineStack>
              ))}
            </InlineStack>
          </BlockStack>
        </Box>

        {/* Right: CTA button */}
        <div style={{ flexShrink: 0 }}>
          <Button variant="secondary" onClick={onFinish}>
            Finish setup →
          </Button>
        </div>
      </InlineStack>
    </Card>
  );
}
